from pathlib import Path

UI = Path("demo/src/main/java/io/github/gallo/sonycamera/demo/CameraScreen.kt")
USB = Path("sonycamera/src/main/java/io/github/gallo/sonycamera/usb/UsbCameraConnectionManager.kt")


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text()
    if old not in text:
        raise RuntimeError(f"Expected block not found in {path}: {old[:180]!r}")
    path.write_text(text.replace(old, new, 1))


