# Panning works in terms of the true viewport center. This avoids a dead zone at
# image edges where magnifyTranslation has already clamped the transform.
replace_once(
    UI,
    """private fun magnifyTranslation(container: IntSize, imageRect: Rect, zoom: Float, pivot: Offset): Offset {\n    if (zoom <= 1f || container == IntSize.Zero || imageRect.width <= 0f) return Offset.Zero\n    val cx = container.width / 2f\n    val cy = container.height / 2f\n    val px = imageRect.left + imageRect.width * pivot.x.coerceIn(0f, 1f)\n    val py = imageRect.top + imageRect.height * pivot.y.coerceIn(0f, 1f)\n    val baseLeft = cx + (imageRect.left - cx) * zoom\n    val baseRight = cx + (imageRect.right - cx) * zoom\n    val baseTop = cy + (imageRect.top - cy) * zoom\n    val baseBottom = cy + (imageRect.bottom - cy) * zoom\n    val minX = container.width - baseRight\n    val maxX = -baseLeft\n    val minY = container.height - baseBottom\n    val maxY = -baseTop\n    return Offset(\n        if (minX <= maxX) (-(px - cx) * zoom).coerceIn(minX, maxX) else 0f,\n        if (minY <= maxY) (-(py - cy) * zoom).coerceIn(minY, maxY) else 0f\n    )\n}\n""",
    """private fun magnifyTranslation(container: IntSize, imageRect: Rect, zoom: Float, pivot: Offset): Offset {\n    if (zoom <= 1f || container == IntSize.Zero || imageRect.width <= 0f) return Offset.Zero\n    val cx = container.width / 2f\n    val cy = container.height / 2f\n    val px = imageRect.left + imageRect.width * pivot.x.coerceIn(0f, 1f)\n    val py = imageRect.top + imageRect.height * pivot.y.coerceIn(0f, 1f)\n    val baseLeft = cx + (imageRect.left - cx) * zoom\n    val baseRight = cx + (imageRect.right - cx) * zoom\n    val baseTop = cy + (imageRect.top - cy) * zoom\n    val baseBottom = cy + (imageRect.bottom - cy) * zoom\n    val minX = container.width - baseRight\n    val maxX = -baseLeft\n    val minY = container.height - baseBottom\n    val maxY = -baseTop\n    return Offset(\n        if (minX <= maxX) (-(px - cx) * zoom).coerceIn(minX, maxX) else 0f,\n        if (minY <= maxY) (-(py - cy) * zoom).coerceIn(minY, maxY) else 0f\n    )\n}\n\nprivate fun magnifyViewportPivot(\n    container: IntSize,\n    imageRect: Rect,\n    zoom: Float,\n    pivot: Offset\n): Offset {\n    if (zoom <= 1f || container == IntSize.Zero || imageRect.width <= 0f || imageRect.height <= 0f) {\n        return Offset(0.5f, 0.5f)\n    }\n    val translation = magnifyTranslation(container, imageRect, zoom, pivot)\n    val cx = container.width / 2f\n    val cy = container.height / 2f\n    val imageCenterX = cx - translation.x / zoom\n    val imageCenterY = cy - translation.y / zoom\n    return Offset(\n        ((imageCenterX - imageRect.left) / imageRect.width).coerceIn(0f, 1f),\n        ((imageCenterY - imageRect.top) / imageRect.height).coerceIn(0f, 1f)\n    )\n}\n\nprivate fun panMagnifyPivot(\n    container: IntSize,\n    imageRect: Rect,\n    zoom: Float,\n    pivot: Offset,\n    dragAmount: Offset\n): Offset {\n    if (zoom <= 1f || imageRect.width <= 0f || imageRect.height <= 0f) return pivot\n    val center = magnifyViewportPivot(container, imageRect, zoom, pivot)\n    return Offset(\n        (center.x - dragAmount.x / (imageRect.width * zoom)).coerceIn(0f, 1f),\n        (center.y - dragAmount.y / (imageRect.height * zoom)).coerceIn(0f, 1f)\n    )\n}\n""",
)

# Invert the actual graphicsLayer transform (including edge-clamped translation)
# when converting a tap to image coordinates. The old formula assumed scaling
# around the image-space pivot and became inaccurate after panning / at edges.
replace_once(
    UI,
    """    val rect = fittedImageRect(container, imageWidth, imageHeight)\n    if (rect.width <= 0f || rect.height <= 0f) return null\n    val screenX = (tap.x - rect.left) / rect.width\n    val screenY = (tap.y - rect.top) / rect.height\n    val x = pivot.x + (screenX - pivot.x) / zoom.coerceAtLeast(1f)\n    val y = pivot.y + (screenY - pivot.y) / zoom.coerceAtLeast(1f)\n    if (x !in 0f..1f || y !in 0f..1f) return null\n    return Offset(x, y)\n""",
    """    val rect = fittedImageRect(container, imageWidth, imageHeight)\n    if (rect.width <= 0f || rect.height <= 0f) return null\n    val safeZoom = zoom.coerceAtLeast(1f)\n    val translation = magnifyTranslation(container, rect, safeZoom, pivot)\n    val cx = container.width / 2f\n    val cy = container.height / 2f\n    val unscaledX = cx + (tap.x - translation.x - cx) / safeZoom\n    val unscaledY = cy + (tap.y - translation.y - cy) / safeZoom\n    val x = (unscaledX - rect.left) / rect.width\n    val y = (unscaledY - rect.top) / rect.height\n    if (x !in 0f..1f || y !in 0f..1f) return null\n    return Offset(x, y)\n""",
)


# ---------------------------------------------------------------------------
# USB manager: a telemetry read started before a user write may complete after
# the write begins and emit stale camera state. Version the control plane and
# discard such snapshots; keep polling quiet briefly after a write so the body
# has time to expose its new value. Serialize user control writes as well.
# ---------------------------------------------------------------------------
replace_once(
    USB,
    """import kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\n""",
    """import kotlinx.coroutines.launch\nimport kotlinx.coroutines.sync.Mutex\nimport kotlinx.coroutines.sync.withLock\nimport kotlinx.coroutines.withContext\n""",
)

replace_once(
    USB,
    """        private const val TELEMETRY_WARMUP_MS = 2_000L\n        private const val FIRST_LIVEVIEW_PROBE_MS = 4_000L\n""",
    """        private const val TELEMETRY_WARMUP_MS = 2_000L\n        private const val CONTROL_POLL_QUIET_MS = 1_000L\n        private const val FIRST_LIVEVIEW_PROBE_MS = 4_000L\n""",
)

replace_once(
    USB,
    """    @Volatile private var postCaptureResumeDeadlineMs = 0L\n\n    // In-flight connect job. Tracking it lets disconnect / detach cancel a\n""",
    """    @Volatile private var postCaptureResumeDeadlineMs = 0L\n\n    // Camera control and telemetry share one PTP transport. A telemetry request\n    // can already be in flight when the user turns a dial; versioning lets us\n    // drop that stale result instead of repainting the UI with the old value.\n    private val controlWriteMutex = Mutex()\n    private val controlEpochLock = Any()\n    @Volatile private var controlEpoch = 0L\n    @Volatile private var telemetryResumeAtMs = 0L\n\n    private fun beginControlWrite(): Long = synchronized(controlEpochLock) {\n        controlEpoch += 1L\n        telemetryResumeAtMs = Long.MAX_VALUE\n        controlEpoch\n    }\n\n    private fun endControlWrite(epoch: Long) = synchronized(controlEpochLock) {\n        if (controlEpoch == epoch) {\n            telemetryResumeAtMs = System.currentTimeMillis() + CONTROL_POLL_QUIET_MS\n        }\n    }\n\n    // In-flight connect job. Tracking it lets disconnect / detach cancel a\n""",
)

replace_once(
    USB,
    """                        val telemetryNow = System.currentTimeMillis()\n                        if (telemetryNow - liveviewStartTime >= TELEMETRY_WARMUP_MS) {\n                            if (telemetryNow - lastSettingsPollTime >= SETTINGS_POLL_INTERVAL_MS) {\n                                lastSettingsPollTime = telemetryNow\n                                ptpCamera?.readCameraSettingsState()?.let { settings ->\n                                    _events.emit(CameraEvent.CameraSettingsUpdated(settings))\n                                }\n                            } else if (telemetryNow - lastExposurePollTime >= EXPOSURE_POLL_INTERVAL_MS) {\n                                lastExposurePollTime = telemetryNow\n                                ptpCamera?.readExposureState()?.let { exposure ->\n                                    _events.emit(CameraEvent.ExposureUpdated(exposure))\n                                }\n                            }\n                        }\n""",
    """                        val telemetryNow = System.currentTimeMillis()\n                        if (telemetryNow - liveviewStartTime >= TELEMETRY_WARMUP_MS &&\n                            telemetryNow >= telemetryResumeAtMs\n                        ) {\n                            if (telemetryNow - lastSettingsPollTime >= SETTINGS_POLL_INTERVAL_MS) {\n                                lastSettingsPollTime = telemetryNow\n                                val pollEpoch = controlEpoch\n                                val settings = ptpCamera?.readCameraSettingsState()\n                                if (settings != null && pollEpoch == controlEpoch &&\n                                    System.currentTimeMillis() >= telemetryResumeAtMs\n                                ) {\n                                    _events.emit(CameraEvent.CameraSettingsUpdated(settings))\n                                } else if (settings != null) {\n                                    Log.d(TAG, \"Discarded stale settings snapshot from control epoch $pollEpoch\")\n                                }\n                            } else if (telemetryNow - lastExposurePollTime >= EXPOSURE_POLL_INTERVAL_MS) {\n                                lastExposurePollTime = telemetryNow\n                                val pollEpoch = controlEpoch\n                                val exposure = ptpCamera?.readExposureState()\n                                if (exposure != null && pollEpoch == controlEpoch &&\n                                    System.currentTimeMillis() >= telemetryResumeAtMs\n                                ) {\n                                    _events.emit(CameraEvent.ExposureUpdated(exposure))\n                                } else if (exposure != null) {\n                                    Log.d(TAG, \"Discarded stale exposure snapshot from control epoch $pollEpoch\")\n                                }\n                            }\n                        }\n""",
)

replace_once(
    USB,
    """    override suspend fun setExposure(\n        setting: CameraExposureSetting,\n        rawValue: Long\n    ): CameraOperationResult = withContext(Dispatchers.IO) {\n        val camera = ptpCamera\n            ?: return@withContext CameraOperationResult.Failure(\"Camera not connected\")\n        val result = camera.setExposureValue(setting, rawValue)\n        _events.emit(CameraEvent.ExposureUpdated(result.state))\n        if (result.success) CameraOperationResult.Success\n        else CameraOperationResult.Failure(result.message ?: \"Exposure change failed\")\n    }\n\n    override suspend fun setCameraSetting(\n        setting: CameraSetting,\n        rawValue: Long\n    ): CameraOperationResult = withContext(Dispatchers.IO) {\n        val camera = ptpCamera\n            ?: return@withContext CameraOperationResult.Failure(\"Camera not connected\")\n        val result = camera.setCameraSettingValue(setting, rawValue)\n        _events.emit(CameraEvent.CameraSettingsUpdated(result.state))\n        if (result.success) CameraOperationResult.Success\n        else CameraOperationResult.Failure(result.message ?: \"Camera setting change failed\")\n    }\n""",
    """    override suspend fun setExposure(\n        setting: CameraExposureSetting,\n        rawValue: Long\n    ): CameraOperationResult = withContext(Dispatchers.IO) {\n        controlWriteMutex.withLock {\n            val camera = ptpCamera\n                ?: return@withLock CameraOperationResult.Failure(\"Camera not connected\")\n            val epoch = beginControlWrite()\n            try {\n                val result = camera.setExposureValue(setting, rawValue)\n                _events.emit(CameraEvent.ExposureUpdated(result.state))\n                if (result.success) CameraOperationResult.Success\n                else CameraOperationResult.Failure(result.message ?: \"Exposure change failed\")\n            } finally {\n                endControlWrite(epoch)\n            }\n        }\n    }\n\n    override suspend fun setCameraSetting(\n        setting: CameraSetting,\n        rawValue: Long\n    ): CameraOperationResult = withContext(Dispatchers.IO) {\n        controlWriteMutex.withLock {\n            val camera = ptpCamera\n                ?: return@withLock CameraOperationResult.Failure(\"Camera not connected\")\n            val epoch = beginControlWrite()\n            try {\n                val result = camera.setCameraSettingValue(setting, rawValue)\n                _events.emit(CameraEvent.CameraSettingsUpdated(result.state))\n                if (result.success) CameraOperationResult.Success\n                else CameraOperationResult.Failure(result.message ?: \"Camera setting change failed\")\n            } finally {\n                endControlWrite(epoch)\n            }\n        }\n    }\n""",
)

# Self-remove: workflow commits only the actual source changes.
Path(__file__).unlink()
print("Applied monitor UI/control synchronization round 3")
